import {attachProductModel} from './product-model.js';
import {pendingPrice,canPurchase} from './catalog-policy.js';
import {thumbnail} from './geometry.js';
import {connected,getProducts,createCheckout} from './shopify.js?v=model-1';
import {shopifyConfig} from './config.js?v=shopify-1';
import {createCartStorage,restoreCart} from './cart-storage.js?v=catalog-2';
const storage=createCartStorage('areas3d:cart:v1:'+ (connected?shopifyConfig.domain:'demo'),{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)});
let catalogReady=false,checkoutBusy=false;
function restore(){const result=restoreCart(storage.read(),products);cart=result.cart;catalogReady=true;renderCart();if(result.changed)notify('Actualizamos tu carrito: algunas piezas ya no están disponibles.');}
const money=p=>new Intl.NumberFormat('es-CO',{style:'currency',currency:p.currencyCode,maximumFractionDigits:0}).format(Number(p.amount));
const examples=[['vase','Vórtice','Jarrón escultórico · diseño paramétrico',68000],['knot','Nudo','Objeto decorativo · geometría continua',42000],['arch','Arco','Objeto escultórico · formas esenciales',54000]].map(([kind,title,description,amount],i)=>({id:`demo-${i}`,kind,title,description,variants:['Azul océano','Blanco polar'].map((title,j)=>({id:`demo-${i}-${j}`,title,availableForSale:true,price:{amount:String(amount),currencyCode:'COP'}}))}));
let products=examples,cart=[];const q=s=>document.querySelector(s);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(text){q('#toast').textContent=text;q('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>q('#toast').classList.remove('visible'),2600)}
let selectedCategory='Todos';
function renderCategories(){
 const host=q('#category-filters');host.replaceChildren();
 const categories=['Todos',...new Set(products.map(p=>p.productType).filter(Boolean))];
 for(const name of categories){const count=name==='Todos'?products.length:products.filter(p=>p.productType===name).length;const button=document.createElement('button');button.type='button';button.textContent=`${name} (${count})`;button.setAttribute('aria-pressed',String(name===selectedCategory));button.onclick=()=>{selectedCategory=name;renderCategories();renderProducts();};host.append(button);}
}
function renderProducts(){q('#products').replaceChildren();products.filter(p=>selectedCategory==='Todos'||p.productType===selectedCategory).forEach((p,i)=>{if(p.kind&&!p.image){try{p.image=thumbnail(p.kind)}catch{}}const b=document.createElement('button');b.className='product';b.innerHTML=`<div class="product-art">${p.image?`<img loading="lazy" src="${escape(p.image)}" alt="${escape(p.alt||p.description)}">`:''}<span class="number">OBJETO / ${String(i+1).padStart(3,'0')}</span></div><div class="product-title"><h3>${escape(p.title)}</h3><span>${pendingPrice(p)?'Precio por definir':money(p.variants[0].price)}</span></div><p>${escape(p.productType||p.description.slice(0,95))}</p>`;b.onclick=()=>detail(p);q('#products').append(b)});}
function detail(p){const v=p.variants;const content=q('#detail-content');content.innerHTML=`${p.image?`<div class="detail-art"><img src="${escape(p.image)}" alt="${escape(p.title)}"></div>`:''}<p class="eyebrow">${escape(connected?(p.productType||'COLECCIÓN'):'PIEZA DE MUESTRA')}</p><h2 id="detail-title">${escape(p.title)}</h2><p class="detail-copy">${escape(p.description.replace(/([^\s])Producto de catálogo/g,'$1 Producto de catálogo'))}</p><label class="variant-label" for="variant">Acabado / Variante</label><select id="variant">${v.map((x,i)=>`<option value="${i}">${escape(x.title)}${pendingPrice(p,x)?'':x.availableForSale?'':' · Agotado'}</option>`).join('')}</select><div class="detail-bottom"><strong id="detail-price"></strong><button class="button" id="add-item">Añadir al carrito</button></div>`;if(v.length===1&&v[0].title==='Default Title'){q('#variant').hidden=true;content.querySelector('.variant-label').hidden=true;}const update=()=>{const selected=v[Number(q('#variant').value)];q('#detail-price').textContent=pendingPrice(p,selected)?'Precio por definir':money(selected.price);q('#add-item').disabled=!canPurchase(p,selected);q('#add-item').textContent=pendingPrice(p,selected)||p.tags?.includes('catalogo-sin-venta')?'Próximamente disponible':selected?.availableForSale?'Añadir al carrito':'Agotado'};q('#variant').onchange=update;update();q('#add-item').onclick=()=>{add(p,v[Number(q('#variant').value)]);q('#product-dialog').close();notify('Pieza añadida al carrito')};q('#product-dialog').showModal();attachProductModel(content,p);}
function add(p,variant){if(!canPurchase(p,variant))throw new Error('Producto todavía no disponible para comprar');const item=cart.find(x=>x.variant.id===variant.id);if(item)item.quantity=Math.min(99,item.quantity+1);else cart.push({product:p,variant,quantity:1});renderCart()}
function renderCart(persist=true){if(catalogReady&&persist)storage.save(cart);q('#cart-count').textContent=cart.reduce((a,l)=>a+l.quantity,0);q('#cart-items').innerHTML=cart.length?'':'<p class="detail-copy">Tu carrito está vacío. Explora la colección y elige una pieza.</p>';cart.forEach(l=>{const row=document.createElement('div');row.className='cart-line';row.innerHTML=`<div><h3>${escape(l.product.title)}</h3><p>${l.variant.title==='Default Title'?'':escape(l.variant.title)+' · '}${money(l.variant.price)}</p></div><div class="quantity"><button aria-label="Quitar una unidad de ${escape(l.product.title)}">−</button><span>${l.quantity}</span><button aria-label="Añadir una unidad de ${escape(l.product.title)}">+</button></div>`;const buttons=row.querySelectorAll('button');buttons[0].onclick=()=>{l.quantity--;cart=cart.filter(x=>x.quantity>0);renderCart()};buttons[1].disabled=l.quantity>=99;buttons[1].onclick=()=>{l.quantity=Math.min(99,l.quantity+1);renderCart()};q('#cart-items').append(row)});q('#cart-total').textContent=money({amount:cart.reduce((a,l)=>a+Number(l.variant.price.amount)*l.quantity,0),currencyCode:cart[0]?.variant.price.currencyCode||'COP'});q('#cart-message').textContent=connected?'El envío, los impuestos y los descuentos se calculan al finalizar la compra.':'Esta es una vista previa con productos y precios de muestra. No se realizan cobros.';if(!storage.available)q('#cart-message').textContent+=' Tu navegador no permite guardar el carrito; se conservará solo mientras esta página esté abierta.';q('#checkout').disabled=!connected||!catalogReady||!cart.length||checkoutBusy;q('#checkout').textContent=connected?'Continuar al pago':'Vista previa · pago no habilitado';}
q('#open-cart').onclick=()=>{renderCart();q('#cart-dialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));q('#checkout').onclick=async()=>{if(checkoutBusy||!connected||!catalogReady||!cart.length)return;checkoutBusy=true;q('#checkout').disabled=true;q('#checkout').textContent='Preparando pago…';try{const url=await createCheckout(cart);const parsed=new URL(url);if(parsed.protocol!=='https:')throw new Error('No se pudo abrir el pago.');location.assign(url)}catch(e){q('#cart-message').textContent=e.message;checkoutBusy=false;q('#checkout').disabled=!cart.length;q('#checkout').textContent='Reintentar pago'}};
renderCart();if(connected){q('#catalog-status').textContent='Cargando colección…';try{products=await getProducts();q('#catalog-status').textContent=products.length?`${products.length} piezas · Precios en pesos colombianos (COP). Explora cada diseño.`:'La colección estará disponible pronto.';renderCategories();renderProducts();restore()}catch(e){products=[];q('#catalog-status').textContent=e.message;const retry=document.createElement('button');retry.textContent='Volver a intentar';retry.className='button';retry.onclick=()=>location.reload();q('#products').append(retry)}}else {renderCategories();renderProducts();restore();}
window.addEventListener('storage',event=>{if(event.key==='areas3d:cart:v1:'+(connected?shopifyConfig.domain:'demo')&&catalogReady){const result=restoreCart(storage.read(),products);cart=result.cart;renderCart(false);}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'view_collection',description:'Read the current collection and whether checkout is available.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('No se admiten parámetros.');return {checkoutEnabled:connected&&products.some(p=>p.variants.some(v=>canPurchase(p,v))),products:products.map(p=>({id:p.id,title:p.title,variants:p.variants}))}}})).catch(()=>{})}catch{}}
